from datetime import datetime, timezone


def format_timestamp(iso_timestamp, target):
    """Format a timezone-aware ISO 8601 timestamp for a project target.

    Analytics timestamps use a UTC SQL-style value, while public API
    timestamps use a UTC RFC 3339 value.
    """
    if target not in {"analytics", "public_api"}:
        raise ValueError(f"unknown timestamp target: {target!r}")

    try:
        timestamp = datetime.fromisoformat(iso_timestamp)
    except (TypeError, ValueError) as exc:
        raise ValueError("iso_timestamp must be a valid ISO 8601 string") from exc

    if timestamp.tzinfo is None or timestamp.utcoffset() is None:
        raise ValueError("iso_timestamp must include a timezone")

    utc_timestamp = timestamp.astimezone(timezone.utc)
    if target == "analytics":
        return utc_timestamp.strftime("%Y-%m-%d %H:%M:%S")
    return utc_timestamp.strftime("%Y-%m-%dT%H:%M:%SZ")
